import ast
import collections

def execute(inputs: dict) -> dict:
    source_code = inputs.get('source_code', '')
    if not source_code or not isinstance(source_code, str):
        return {
            "summary": "No source code provided for analysis.",
            "findings": []
        }

    findings = []
    try:
        tree = ast.parse(source_code)
    except SyntaxError as e:
        return {
            "summary": "Analysis failed due to syntax errors.",
            "findings": [{
                "issue_description": "Syntax Error",
                "severity": "High",
                "explanation": f"The provided code is not valid Python: {str(e)}",
                "suggested_fix": "Correct the syntax errors in the source code.",
                "corrected_code": None
            }]
        }

    # Analysis State
    defined_vars = set(['True', 'False', 'None', 'print', 'len', 'range', 'int', 'str', 'list', 'dict', 'set', 'sum', 'max', 'min', 'open'])

    class BugAnalyzer(ast.NodeVisitor):
        def __init__(self):
            self.issues = []
            self.current_function = None
            self.local_vars = set()

        def visit_FunctionDef(self, node):
            # Track function name as defined
            defined_vars.add(node.name)

            # Check for missing return statements
            has_return = False
            for child in ast.walk(node):
                if isinstance(child, ast.Return):
                    has_return = True
                    break

            if not has_return:
                self.issues.append({
                    "issue_description": "Missing Return Statement",
                    "severity": "Low",
                    "explanation": f"Function '{node.name}' does not return a value. If this is intended, consider adding 'return None'.",
                    "suggested_fix": "Add a return statement if the function is expected to return a value.",
                    "corrected_code": None
                })

            # Scope management for variables
            old_locals = self.local_vars.copy()
            self.local_vars.add(node.name)
            for arg in node.args.args:
                self.local_vars.add(arg.arg)

            self.generic_visit(node)
            self.local_vars = old_locals

        def visit_Assign(self, node):
            for target in node.targets:
                if isinstance(target, ast.Name):
                    self.local_vars.add(target.id)
                    defined_vars.add(target.id)
            self.generic_visit(node)

        def visit_Name(self, node):
            if isinstance(node.ctx, ast.Load):
                if node.id not in defined_vars and node.id not in self.local_vars:
                    self.issues.append({
                        "issue_description": "Undefined Variable",
                        "severity": "High",
                        "explanation": f"Variable '{node.id}' is used but not defined in the current scope.",
                        "suggested_fix": f"Define '{node.id}' before using it.",
                        "corrected_code": None
                    })
            self.generic_visit(node)

        def visit_If(self, node):
            # Check for empty blocks (pass is okay, but empty is not)
            if not node.body:
                self.issues.append({
                    "issue_description": "Empty If Block",
                    "severity": "Medium",
                    "explanation": "The 'if' block is empty, which may indicate incomplete logic.",
                    "suggested_fix": "Add logic to the if block or use 'pass'.",
                    "corrected_code": None
                })
            self.generic_visit(node)

    analyzer = BugAnalyzer()
    analyzer.visit(tree)
    findings = analyzer.issues

    summary = f"Analysis complete. Found {len(findings)} potential issue(s)."

    return {
        "summary": summary,
        "findings": findings
    }

